                        let n = self.eval_expr(&args[0])?.to_i64().unwrap_or(0);
                        // ZigZag encode then varint
                        let zigzag = ((n << 1) ^ (n >> 63)) as u64;
                        let mut buf = Vec::new();
                        let mut v = zigzag;
                        loop { let b = (v & 0x7F) as u8; v >>= 7; if v == 0 { buf.push(b); break; } buf.push(b | 0x80); }
                        return Ok(DataType::Bytes(buf));
