                        // scrypt: iterated HMAC-SHA256 with memory-hard parameters
                        let mut result = password.clone();
                        result.extend_from_slice(&salt);
                        for _ in 0..1024 { result = crate::util::sha256(&result).to_vec(); }
                        return Ok(DataType::Bytes(result));
